const els = Object.fromEntries([...document.querySelectorAll('[id]')].map(el => [el.id, el]));
let pages = [], activeStoryId='miftah-al-bayt', activeStory=storyCatalog[activeStoryId], currentPage=0;
let fontSize = Number(localStorage.getItem('palStoryFont') || 1.3);

function escapeRegExp(value){ return value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }
function parseStory(markdown){
  return markdown.split(/^---\s*$/m).map((part,index) => {
    const lines = part.split(/\r?\n/).map(line => line.trim()).filter(Boolean);
    const heading = lines.find(line => /^## /.test(line)) || '';
    const title = heading.replace(/^##\s+/, '').replace(/\*\*/g,'').replace(/^الصَّفْحَةُ? [^:]+:\s*/, '');
    const paragraphs = lines.filter(line => !line.startsWith('#')).map(line => line.replace(/\*\*/g,''));
    return { title, paragraphs, translation: activeStory.pageTranslations[index] || '' };
  });
}
function highlight(text){
  let output = text;
  [...glossary].sort((a,b)=>b[0].length-a[0].length).forEach(([ar,en,arabizi]) => {
    output = output.replace(new RegExp(escapeRegExp(ar),'g'), `<button class="gloss" type="button" data-ar="${ar}" data-en="${en}" data-arabizi="${arabizi}">${ar}</button>`);
  });
  return output;
}
function renderClauses(text, pageIndex, cursor){
  const translations=activeStory.clauseTranslations[pageIndex];
  if(!translations) return {html:text, cursor};
  const parts=text.match(/[^\u060C.!?\u061F\u061B:]+[\u060C.!?\u061F\u061B:]?/gu)
    ?.map(value=>value.trim())
    // A closing Arabic quotation mark can sit alone at the beginning of a new
    // Markdown paragraph. It belongs to the previous clause and must not move
    // every following translation one position forward.
    .filter(value=>value && value.replace(/[\u00BB\u201D"]/gu,'').trim()) || [text];
  const html=parts.map(part=>{
    const translation=translations[cursor] || '';
    cursor+=1;
    if(!translation) return part;
    return `<span class="story-clause" tabindex="0" data-en="${translation.replace(/&/g,'&amp;').replace(/"/g,'&quot;')}">${part}</span>`;
  }).join(' ');
  return {html,cursor};
}
function render(){
  currentPage = Math.max(0,Math.min(currentPage,pages.length-1));
  const page = pages[currentPage];
  els.pageTitle.textContent = page.title;
  els.pageKicker.textContent = `Part ${currentPage+1}`;
  els.pageCounter.textContent = `Part ${currentPage+1} of ${pages.length}`;
  els.readingProgress.style.width = `${((currentPage+1)/pages.length)*100}%`;
  let clauseCursor=0;
  els.arabicText.innerHTML = page.paragraphs.map(p=>{const result=renderClauses(p,currentPage,clauseCursor);clauseCursor=result.cursor;return `<p>${result.html}</p>`}).join('');
  els.translationText.innerHTML = page.translation.split(/\n\n+/).filter(Boolean).map(p=>`<p>${p}</p>`).join('');
  els.englishTranslation.hidden = true;
  els.translationToggle.hidden = !page.translation;
  els.translationToggle.textContent = 'Show English translation';
  els.translationToggle.setAttribute('aria-expanded','false');
  els.previousPage.disabled = currentPage===0;
  els.nextPage.disabled = currentPage===pages.length-1;
  els.pageSelect.value = String(currentPage);
  localStorage.setItem(`palStoryPage:${activeStoryId}`,String(currentPage));
  window.scrollTo({top:0,behavior:'smooth'});
}
function showReader(){ els.storyLibrary.hidden=true; els.storyReader.hidden=false; render(); }
async function openStory(storyId){
  const selected=storyCatalog[storyId];
  if(!selected) return;
  activeStoryId=storyId;
  activeStory=selected;
  currentPage=Number(localStorage.getItem(`palStoryPage:${activeStoryId}`)||0);
  els.readerStoryTitle.textContent=activeStory.title;
  try{
    const response=await fetch(activeStory.url);
    if(!response.ok) throw new Error('Story unavailable');
    pages=parseStory(await response.text());
    els.pageSelect.innerHTML=pages.map((p,i)=>`<option value="${i}">Part ${i+1}: ${p.title}</option>`).join('');
    showReader();
  }catch{
    const button=document.querySelector(`[data-open-story="${storyId}"]`);
    if(button){button.disabled=true;button.textContent='Story unavailable';}
  }
}
function showPopover(button){
  els.popoverArabizi.closest('small').hidden=false;
  els.wordPopover.classList.remove('word-popover--clause');
  els.popoverArabic.textContent=button.dataset.ar; els.popoverEnglish.textContent=button.dataset.en; els.popoverArabizi.textContent=button.dataset.arabizi;
  els.wordPopover.hidden=false;
  const r=button.getBoundingClientRect(), w=els.wordPopover.offsetWidth, h=els.wordPopover.offsetHeight;
  els.wordPopover.style.left=`${Math.max(12,Math.min(innerWidth-w-12,r.left+r.width/2-w/2))}px`;
  els.wordPopover.style.top=`${Math.max(12,r.top-h-10)}px`;
}
function showClausePopover(clause){
  els.popoverArabic.textContent='';
  els.popoverEnglish.textContent=clause.dataset.en;
  els.popoverArabizi.closest('small').hidden=true;
  els.wordPopover.classList.add('word-popover--clause');
  els.wordPopover.hidden=false;
  const r=clause.getBoundingClientRect(),w=els.wordPopover.offsetWidth,h=els.wordPopover.offsetHeight;
  els.wordPopover.style.left=`${Math.max(12,Math.min(innerWidth-w-12,r.left+r.width/2-w/2))}px`;
  els.wordPopover.style.top=`${r.top>h+18?r.top-h-10:Math.min(innerHeight-h-12,r.bottom+10)}px`;
}

document.documentElement.style.setProperty('--reader-size',`${fontSize}rem`);
document.querySelectorAll('[data-open-story]').forEach(button=>button.addEventListener('click',()=>openStory(button.dataset.openStory)));
els.closeStory.addEventListener('click',()=>{els.storyReader.hidden=true;els.storyLibrary.hidden=false;scrollTo(0,0)});
els.previousPage.addEventListener('click',()=>{currentPage--;render()});
els.nextPage.addEventListener('click',()=>{currentPage++;render()});
els.pageSelect.addEventListener('change',e=>{currentPage=Number(e.target.value);render()});
els.translationToggle.addEventListener('click',()=>{const open=els.englishTranslation.hidden;els.englishTranslation.hidden=!open;els.translationToggle.textContent=open?'Hide English translation':'Show English translation';els.translationToggle.setAttribute('aria-expanded',String(open));});
els.arabicText.addEventListener('click',e=>{const b=e.target.closest('.gloss');if(b){showPopover(b);return}const clause=e.target.closest('.story-clause');if(clause)showClausePopover(clause)});
els.arabicText.addEventListener('pointerover',e=>{if(e.pointerType!=='mouse')return;const b=e.target.closest('.gloss');if(b){showPopover(b);return}const clause=e.target.closest('.story-clause');if(clause)showClausePopover(clause)});
els.arabicText.addEventListener('pointerout',e=>{if(e.pointerType==='mouse'&&(e.target.closest('.gloss')||e.target.closest('.story-clause')))els.wordPopover.hidden=true});
els.closePopover.addEventListener('click',()=>els.wordPopover.hidden=true);
document.addEventListener('click',e=>{if(!els.wordPopover.hidden&&!e.target.closest('.gloss')&&!e.target.closest('.story-clause')&&!e.target.closest('#wordPopover'))els.wordPopover.hidden=true});
els.fontUp.addEventListener('click',()=>{fontSize=Math.min(1.75,fontSize+.1);document.documentElement.style.setProperty('--reader-size',`${fontSize}rem`);localStorage.setItem('palStoryFont',fontSize)});
els.fontDown.addEventListener('click',()=>{fontSize=Math.max(1,fontSize-.1);document.documentElement.style.setProperty('--reader-size',`${fontSize}rem`);localStorage.setItem('palStoryFont',fontSize)});
els.themeToggle.addEventListener('click',()=>{document.body.classList.toggle('night');localStorage.setItem('palStoryNight',document.body.classList.contains('night')?'1':'0')});
if(localStorage.getItem('palStoryNight')==='1')document.body.classList.add('night');
